import { attachSaveStatus } from "./save-status.js";
import { createTrailingTask } from "./trailing-task.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  let navigation = 0;

  function leaveCurrent() {
    const leaving = current;
    current = null;
    if (leaving) leaving.stop();
    renderDocument(null);
    if (leaving) leaving.save.flush();
  }

  function close() {
    navigation += 1;
    leaveCurrent();
  }
  return {
    open(id) {
      const request = ++navigation;
      leaveCurrent();
      if (request !== navigation) return;

      const save = createTrailingTask(
        (documentId, text) => store.write(documentId, text),
        120,
        timers,
      );
      current = {
        id,
        save,
        stop: attachSaveStatus(store, id, renderStatus),
      };
      renderDocument({ id, text: store.read(id) });
    },
    edit(text) {
      if (current) current.save.push(current.id, text);
    },
    close,
  };
}

